# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMC-000001",
    "name": "Wai 偉",
    "kind": "first-name",
    "meaning": "Wai (偉) is a masculine given name in Cantonese. Meaning: Great. The Cantonese reading of the same character as Mandarin "
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Wai")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

